begin;
create table platform.notification_push_subscriptions(id uuid primary key default extensions.gen_random_uuid(),user_id uuid not null references platform.profiles(user_id) on delete cascade,device_id uuid not null references platform.devices(id) on delete cascade,endpoint text not null check(endpoint like 'https://%' and char_length(endpoint)<=2048),p256dh text not null check(char_length(p256dh) between 40 and 256),auth_secret text not null check(char_length(auth_secret) between 16 and 128),module_keys text[] not null default '{}'::text[] check(module_keys <@ array['conference','reservations','warehouse','platform']::text[]),user_agent text not null default '' check(char_length(user_agent)<=512),active boolean not null default true,created_at timestamptz not null default statement_timestamp(),updated_at timestamptz not null default statement_timestamp(),unique(endpoint));
create index notification_push_subscriptions_user_device_idx on platform.notification_push_subscriptions(user_id,device_id) where active;
alter table platform.notification_push_subscriptions enable row level security; alter table platform.notification_push_subscriptions force row level security; revoke all on platform.notification_push_subscriptions from public,anon,authenticated,service_role;
create table platform.notification_events(id uuid primary key default extensions.gen_random_uuid(),event_type text not null check(event_type ~ '^[a-z0-9_.-]{3,120}$'),module_key text not null check(module_key in('conference','reservations','warehouse','platform')),resource_type text not null check(resource_type ~ '^[a-z0-9_.-]{1,80}$'),resource_id text,title text not null check(char_length(title) between 1 and 160),body text not null check(char_length(body) between 1 and 500),target_url text not null check(char_length(target_url) between 1 and 1000),dedupe_key text not null check(char_length(dedupe_key) between 1 and 240),created_at timestamptz not null default statement_timestamp(),unique(dedupe_key));
alter table platform.notification_events enable row level security; alter table platform.notification_events force row level security; revoke all on platform.notification_events from public,anon,authenticated,service_role;
create table platform.notification_deliveries(id uuid primary key default extensions.gen_random_uuid(),notification_event_id uuid not null references platform.notification_events(id) on delete cascade,subscription_id uuid not null references platform.notification_push_subscriptions(id) on delete cascade,status text not null default 'pending' check(status in('pending','sent','failed','expired')),attempt_count integer not null default 0 check(attempt_count>=0),last_attempt_at timestamptz,last_error_code text,delivered_at timestamptz,unique(notification_event_id,subscription_id));
create index notification_deliveries_pending_idx on platform.notification_deliveries(status,notification_event_id) where status in('pending','failed');
alter table platform.notification_deliveries enable row level security; alter table platform.notification_deliveries force row level security; revoke all on platform.notification_deliveries from public,anon,authenticated,service_role;
create or replace function platform_private.upsert_notification_push_subscription(p_actor_device_id uuid,p_endpoint text,p_p256dh text,p_auth text,p_module_keys text[],p_user_agent text) returns jsonb language plpgsql security definer set search_path='' as $$declare ctx jsonb;actor uuid;item text;row_id uuid;begin ctx:=nullif(pg_catalog.current_setting('platform.phase1c_context',true),'')::jsonb;if ctx is null or ctx->>'purpose'<>'PLATFORM_DEVICE_SESSION_DISPATCH' or (ctx->>'device_id')::uuid is distinct from p_actor_device_id then raise exception 'APPROVED_DEVICE_SESSION_REQUIRED' using errcode='42501';end if;actor:=(ctx->>'user_id')::uuid;if p_endpoint is null or p_endpoint not like 'https://%' or char_length(p_endpoint)>2048 or char_length(coalesce(p_p256dh,'')) not between 40 and 256 or char_length(coalesce(p_auth,'')) not between 16 and 128 or cardinality(p_module_keys)=0 or p_module_keys is distinct from array(select distinct x from unnest(p_module_keys)x order by x) then raise exception 'PLATFORM_NOTIFICATION_SUBSCRIPTION_INVALID' using errcode='22023';end if;foreach item in array p_module_keys loop if item not in('conference','reservations','warehouse','platform') then raise exception 'PLATFORM_NOTIFICATION_MODULE_INVALID' using errcode='22023';end if;if item<>'platform' then perform public.require_effective_module_permission(p_actor_device_id,item,item||'.module.access',null,null);end if;end loop;insert into platform.notification_push_subscriptions(user_id,device_id,endpoint,p256dh,auth_secret,module_keys,user_agent) values(actor,p_actor_device_id,p_endpoint,p_p256dh,p_auth,p_module_keys,left(coalesce(p_user_agent,''),512)) on conflict(endpoint) do update set user_id=excluded.user_id,device_id=excluded.device_id,p256dh=excluded.p256dh,auth_secret=excluded.auth_secret,module_keys=excluded.module_keys,user_agent=excluded.user_agent,active=true,updated_at=statement_timestamp() returning id into row_id;return jsonb_build_object('subscriptionId',row_id,'active',true,'moduleKeys',p_module_keys);end$$;
revoke all on function platform_private.upsert_notification_push_subscription(uuid,text,text,text,text[],text) from public,anon,authenticated,service_role;
create or replace function platform_private.disable_notification_push_subscription(p_actor_device_id uuid,p_endpoint text) returns jsonb language plpgsql security definer set search_path='' as $$declare ctx jsonb;actor uuid;changed integer;begin ctx:=nullif(pg_catalog.current_setting('platform.phase1c_context',true),'')::jsonb;if ctx is null or ctx->>'purpose'<>'PLATFORM_DEVICE_SESSION_DISPATCH' or (ctx->>'device_id')::uuid is distinct from p_actor_device_id then raise exception 'APPROVED_DEVICE_SESSION_REQUIRED' using errcode='42501';end if;actor:=(ctx->>'user_id')::uuid;update platform.notification_push_subscriptions set active=false,updated_at=statement_timestamp() where user_id=actor and device_id=p_actor_device_id and endpoint=p_endpoint and active;get diagnostics changed=row_count;return jsonb_build_object('disabled',changed>0);end$$;
revoke all on function platform_private.disable_notification_push_subscription(uuid,text) from public,anon,authenticated,service_role;
create or replace function platform_private.enqueue_notification(p_event_type text,p_module_key text,p_resource_type text,p_resource_id text,p_title text,p_body text,p_target_url text,p_dedupe_key text) returns jsonb language plpgsql security definer set search_path='' as $$declare event_id uuid;inserted boolean:=false;delivery_count integer;begin if coalesce(auth.jwt()->>'role','')<>'service_role' then raise exception 'PLATFORM_NOTIFICATION_BACKEND_REQUIRED' using errcode='42501';end if;if p_module_key not in('conference','reservations','warehouse','platform') or p_event_type !~ '^[a-z0-9_.-]{3,120}$' or p_resource_type !~ '^[a-z0-9_.-]{1,80}$' or char_length(coalesce(p_title,'')) not between 1 and 160 or char_length(coalesce(p_body,'')) not between 1 and 500 or char_length(coalesce(p_target_url,'')) not between 1 and 1000 or char_length(coalesce(p_dedupe_key,'')) not between 1 and 240 then raise exception 'PLATFORM_NOTIFICATION_EVENT_INVALID' using errcode='22023';end if;insert into platform.notification_events(event_type,module_key,resource_type,resource_id,title,body,target_url,dedupe_key) values(p_event_type,p_module_key,p_resource_type,p_resource_id,p_title,p_body,p_target_url,p_dedupe_key) on conflict(dedupe_key) do nothing returning id into event_id;if event_id is null then select id into event_id from platform.notification_events where dedupe_key=p_dedupe_key;else inserted:=true;end if;insert into platform.notification_deliveries(notification_event_id,subscription_id) select event_id,s.id from platform.notification_push_subscriptions s where s.active and p_module_key=any(s.module_keys) on conflict(notification_event_id,subscription_id) do nothing;get diagnostics delivery_count=row_count;return jsonb_build_object('notificationEventId',event_id,'created',inserted,'queuedDeliveries',delivery_count);end$$;
revoke all on function platform_private.enqueue_notification(text,text,text,text,text,text,text,text) from public,anon,authenticated;grant execute on function platform_private.enqueue_notification(text,text,text,text,text,text,text,text) to service_role;
do $patch$ declare source_sql text;updated_sql text;needle text;begin source_sql:=pg_get_functiondef('platform.execute_device_operation(uuid,uuid,bytea,text,text,jsonb)'::regprocedure);if position('upsert_notification_push_subscription' in source_sql)>0 then return;end if;needle:='when ''recover_revoke_final_module_manager'' then';if position(needle in source_sql)=0 then raise exception 'PLATFORM_NOTIFICATION_DISPATCHER_DRIFT';end if;updated_sql:=replace(source_sql,needle,'when ''upsert_notification_push_subscription'' then perform platform_private.require_exact_jsonb_keys(p_args,array[''p_endpoint'',''p_p256dh'',''p_auth'',''p_module_keys'',''p_user_agent'']);return platform_private.upsert_notification_push_subscription(v_session.device_id,p_args->>''p_endpoint'',p_args->>''p_p256dh'',p_args->>''p_auth'',array(select jsonb_array_elements_text(p_args->''p_module_keys'')),p_args->>''p_user_agent'');when ''disable_notification_push_subscription'' then perform platform_private.require_exact_jsonb_keys(p_args,array[''p_endpoint'']);return platform_private.disable_notification_push_subscription(v_session.device_id,p_args->>''p_endpoint'');'||needle);execute updated_sql;end$patch$;
commit;
